function pick_endpoint(candidates, policy, request):
  // candidates: list of {endpoint, latency, cost, error_rate, region}
  for c in candidates: 
    c.norm_latency = min(c.latency / policy.latency_hard_bound, 1.0)
    c.norm_cost = c.cost / baseline_cost(request.model)
    c.norm_unreliability = clamp(c.error_rate * error_weight, 0, 1)
    c.score = 1 - (policy.w_latency*c.norm_latency + policy.w_cost*c.norm_cost + policy.w_reliability*c.norm_unreliability)
  filtered = filter(candidates, lambda c: meets_safety_gates(c, request))
  sort_desc(filtered, key=lambda c: c.score)
  return apply_tiered_maneuvers(filtered, policy, request)
